import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DzNHXt93.js";const b=JSON.parse('{"title":"Form Proposal: ObjectBucket","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/object-bucket.md","filePath":"proposals/object-bucket.md"}'),i={name:"proposals/object-bucket.md"};function s(n,e,c,l,d,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="form-proposal-objectbucket" tabindex="-1">Form Proposal: ObjectBucket <a class="header-anchor" href="#form-proposal-objectbucket" aria-label="Permalink to &quot;Form Proposal: ObjectBucket&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need-and-boundary" tabindex="-1">Need and boundary <a class="header-anchor" href="#need-and-boundary" aria-label="Permalink to &quot;Need and boundary&quot;">​</a></h2><p>Takosumi Cloud provides durable object storage. The candidate Form describes a bucket identity, version-retention semantics, lifecycle, and <code>object.storage@1</code> Interface. Region, storage class, replication, physical store, capacity, credentials, endpoint/protocol compatibility, policy, and pricing remain host-owned.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>Version retention and object operations can have the same meaning over S3, R2, GCS, a filesystem-backed host, or another object store. <code>s3_api</code>, storage classes, endpoint shapes, region, and replication are excluded because they belong to an adapter, support profile, or Service Offering.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Location or storage-policy changes can require migration. Deleting a non-empty bucket risks irreversible loss and must follow explicit host retention policy. Import requires exact ownership evidence. Keys, signed URLs, object contents, and credentials never enter portable Resource state.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI Storage/Link, CIMI Volume lifecycle, TOSCA object-storage nodes, Kubernetes ObjectBucketClaim, Crossplane buckets, and Terraform S3/R2/GCS/ Azure resources are applicable. The gap is a backend-neutral bucket lifecycle paired with an explicit object Interface and no credential transport.</p>',10)])])}const h=a(i,[["render",s]]);export{b as __pageData,h as default};
